ALTER TABLE public.tryout_registrations ADD COLUMN IF NOT EXISTS tryout_plan_id text, ADD COLUMN IF NOT EXISTS season_name text, ADD COLUMN IF NOT EXISTS status text DEFAULT 'registered', ADD COLUMN IF NOT EXISTS bib_number integer;
DO $seed$
DECLARE t public.teams%ROWTYPE; p public.players%ROWTYPE; i integer := 0; yr text; pid text; oid text; base numeric; dues jsonb;
BEGIN
 SELECT * INTO t FROM public.teams WHERE id='es-t1' AND club_id='eclipse-select' AND is_sample=true;
 IF NOT FOUND THEN RAISE EXCEPTION 'Expected Eclipse demo 2010 team missing; no seed applied'; END IF;
 UPDATE public.clubs SET logo_url='/__l5e/assets-v1/bef38264-a65f-47bf-926e-f9e44fc614ec/eclipse-select-logo.png',primary_color='#071c35',secondary_color='#45e3e5' WHERE id=t.club_id AND is_demo=true;
 INSERT INTO public.seasons(id,club_id,name,start_date,end_date,is_current,status,is_sample,notes) VALUES ('es-season-2728',t.club_id,'2027-28','2027-08-01','2028-07-31',false,'draft',true,'Demo next season; dates are illustrative.') ON CONFLICT(id) DO NOTHING;
 FOREACH yr IN ARRAY ARRAY['2026-27','2027-28'] LOOP
  pid := CASE WHEN yr='2026-27' THEN 'es-2010-plan-2627' ELSE 'es-2010-plan-2728' END;
  oid := CASE WHEN yr='2026-27' THEN 'es-2010-dues-2627' ELSE 'es-2010-dues-2728' END;
  base := CASE WHEN yr='2026-27' THEN 3400 ELSE 3500 END;
  dues := jsonb_build_object('base_dues',base,'included_services',jsonb_build_array('Licensed coaching and three weekly team sessions','Fall and spring field rental; winter indoor training','ECNL league registration and referee fees','Quarterly skill tests, physical assessments and coach feedback','Club curriculum and individual development review'),'team_fees',jsonb_build_array(jsonb_build_object('id','showcases','name','Team showcase entries','description','Two regional team showcase entry fees; family travel not included.','amount',300,'required',true),jsonb_build_object('id','extra-skills','name','Optional small-group skills','description','Six additional small-group technical sessions.','amount',180,'required',false),jsonb_build_object('id','video','name','Optional recruiting video review','description','Individual match video review and recruiting clips.','amount',120,'required',false)));
  INSERT INTO public.offers(id,club_id,name,description,type,access,status,config,is_sample) VALUES(oid,t.club_id,t.name||' — '||yr||' Dues (Demo)','Illustrative demo prices, not official Eclipse fees. No live payment connection.','dues','members_only',CASE WHEN yr='2026-27' THEN 'active' ELSE 'draft' END,jsonb_build_object('amount',base+300,'dues',dues,'season',yr,'team_id',t.id,'team_name',t.name,'payment_plans',jsonb_build_array('full')),true) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.team_plans(id,club_id,team_id,offer_id,team_name,age_group,gender,playing_format,branch_id,branch_name,platform_name,season,coach_id,coach_name,fall_training,winter_training,spring_training,league_games,tournament_count,tournament_names,included_programs,club_dues,included_services,team_fees,payment_plans,is_template,status,notes,is_sample) VALUES(pid,t.club_id,t.id,oid,t.name,CASE WHEN yr='2026-27' THEN 'U17' ELSE 'U18' END,t.gender,'11v11',t.location_id,t.location_name,'ECNL',yr,t.coach_id,t.coach_name,'Three sessions weekly: first touch, combination play, tactical transition.','Two indoor sessions plus weekly strength and mobility.','Three sessions weekly: match preparation, positional play and finishing.','ECNL Midwest fixtures; schedule is illustrative.',2,jsonb_build_array('Midwest Fall Showcase (demo)','Spring College Showcase (demo)'),jsonb_build_array('Center of Excellence','Player Development'),base,dues->'included_services',dues->'team_fees',jsonb_build_array('full'),false,CASE WHEN yr='2026-27' THEN 'active' ELSE 'draft' END,'Demo plan; illustrative prices and services. Next-season draft does not replace current-season dues.',true) ON CONFLICT(id) DO NOTHING;
 END LOOP;
 INSERT INTO public.tryout_plans(id,club_id,title,age_group,gender,format,season,start_date,end_date,team_ids,team_names,location_ids,location_names,platform_names,status,lead_name,notes,is_sample) VALUES('es-2010-tryout-2728',t.club_id,'2010 Girls ECNL — 2027–28 Returning Players & Recruitment (Demo)','U18','Girls','11v11','2027-28','2027-05-10','2027-05-12',jsonb_build_array(t.id),jsonb_build_array(t.name),jsonb_build_array(t.location_id),jsonb_build_array(t.location_name),jsonb_build_array('ECNL'),'draft',t.coach_name,'Illustrative demo tryout dates, not official Eclipse dates. Returning players reviewed alongside new recruits; next-season dues remain draft.',true) ON CONFLICT(id) DO NOTHING;
 INSERT INTO public.tryout_events(id,club_id,tryout_plan_id,type,is_anchor,date,start_time,end_time,location,expected_attendance,auto_registration,stage,registration_count,checked_in_count,evaluated_count,notes,is_sample) VALUES
 ('es-2010-main-2728',t.club_id,'es-2010-tryout-2728','main_tryout',true,'2027-05-10','17:30','19:00',t.location_name||' — Turf Field (demo)',24,false,'planned',16,0,0,'Demo main session: technical stations, small-sided play, 11v11 evaluation. Arrive 20 minutes early.',true),
 ('es-2010-recall-2728',t.club_id,'es-2010-tryout-2728','supplemental',false,'2027-05-12','17:30','19:00',t.location_name||' — Turf Field (demo)',24,false,'planned',0,0,0,'Demo callback: positional review and full-sided match play.',true) ON CONFLICT(id) DO NOTHING;
 INSERT INTO public.calendar_events(id,club_id,title,event_type,start_datetime,end_datetime,team_ids,team_names,season,location_text,rsvp_required,visibility,is_sample,notes) VALUES
 ('es-2010-cal-main',t.club_id,'2010 Girls ECNL Tryout — Main Session (Demo)','tryout','2027-05-10T17:30:00-05:00','2027-05-10T19:00:00-05:00',jsonb_build_array(t.id),jsonb_build_array(t.name),'2027-28',t.location_name,true,'team',true,'Illustrative demo date, not an official club tryout.'),
 ('es-2010-cal-recall',t.club_id,'2010 Girls ECNL Tryout — Callback (Demo)','tryout','2027-05-12T17:30:00-05:00','2027-05-12T19:00:00-05:00',jsonb_build_array(t.id),jsonb_build_array(t.name),'2027-28',t.location_name,true,'team',true,'Illustrative demo date, not an official club tryout.') ON CONFLICT(id) DO NOTHING;
 FOR p IN SELECT * FROM public.players WHERE club_id=t.club_id AND team_id=t.id AND is_sample=true ORDER BY id LOOP
  i := i+1;
  INSERT INTO public.tryout_registrations(id,club_id,player_id,player_name,tryout_event_id,tryout_plan_id,desired_age_group,registered_date,season_name,status,bib_number,checked_in,attended,notes,is_sample) VALUES('es-2010-reg-'||p.id,t.club_id,p.id,p.first_name||' '||p.last_name,'es-2010-main-2728','es-2010-tryout-2728','U18','2026-11-03','2027-28','registered',100+i,false,false,'Returning player from 2010 Girls ECNL. Demo registration; no invitation sent.',true) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.skill_test_scores(id,club_id,player_id,player_name,test_id,test_title,test_date,score,logged_by,notes,is_sample) VALUES('es-2010-juggle-'||p.id,t.club_id,p.id,p.first_name||' '||p.last_name,'es-sk3','Juggling (max)','2026-11-01',45+i*4,t.coach_name,'Demo baseline for returning-player review.',true) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.physical_assessments(id,club_id,player_id,player_name,assessment_date,sprint_20m_seconds,agility_5_10_5_seconds,vertical_jump_inches,yoyo_level,speed,agility,endurance,power,recovery,lean,overall,assessed_by,notes,is_sample) VALUES('es-2010-physical-'||p.id,t.club_id,p.id,p.first_name||' '||p.last_name,'2026-11-01',3.30+(i%5)*0.08,4.7+(i%4)*0.1,17+(i%6),14+(i%4),76+(i%10),72+(i%12),78+(i%9),73+(i%10),80+(i%8),75+(i%10),77+(i%9),'Performance Staff (demo)','Demo athletic profile; not medical advice.',true) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.player_evaluations(id,club_id,player_id,player_name,evaluation_date,evaluator_email,primary_position,preferred_foot,technical_scores,tactical_scores,mental_scores,physical_score,overall_score,strengths,areas_of_growth,training_focus,status,is_sample) VALUES('es-2010-eval-'||p.id,t.club_id,p.id,p.first_name||' '||p.last_name,'2026-11-01','coach@example.invalid',p.position,'Right',jsonb_build_object('first_touch',3+(i%3),'passing',4,'dribbling',3+(i%2),'shooting',3+(i%3)),jsonb_build_object('positioning',4,'decision_making',3+(i%3),'transition',4),jsonb_build_object('coachability',5,'composure',4,'leadership',3+(i%3)),4,3.7+(i%6)*0.2,'Receives on the half turn; supports teammates and responds to coaching.','Scan before receiving; improve weak-foot passing under pressure.','Two weekly weak-foot ball-work blocks and video review of defensive transition.','completed',true) ON CONFLICT(id) DO NOTHING;
  INSERT INTO public.player_feedbacks(id,club_id,player_id,player_name,feedback_text,strengths,development_priorities,suggested_goal_description,suggested_goal_target,status,sent_at,tone,is_sample) VALUES('es-2010-feedback-'||p.id,t.club_id,p.id,p.first_name||' '||p.last_name,'Demo coach feedback: Strong progress in receiving and connecting play. Keep scanning before the ball arrives and use both feet in tight spaces. We will review your progress before the next-season tryouts.',jsonb_build_array('Positive response to coaching','Combination play and supporting angles'),jsonb_build_array('Weak-foot passing accuracy','Scanning before receiving'), 'Complete three 15-minute weak-foot sessions weekly','Review at the next development check-in','sent','2026-11-02T17:00:00Z','developmental',true) ON CONFLICT(id) DO NOTHING;
 END LOOP;
 UPDATE public.teams SET player_ids=(SELECT jsonb_agg(id ORDER BY id) FROM public.players WHERE club_id=t.club_id AND team_id=t.id),team_plans=(SELECT jsonb_build_object('season',season,'club_dues',club_dues,'included_services',included_services,'team_fees',team_fees)::text FROM public.team_plans WHERE id='es-2010-plan-2627' AND club_id=t.club_id),cost=3700 WHERE id=t.id AND club_id=t.club_id AND is_sample=true;
END $seed$;